// Неофициальные классы без ячеек заклинаний: умения и сила описаны текстом.
func init() {
	for _, ln := range strings.Split(subclassTable, "\n") {
		p := strings.SplitN(strings.TrimSpace(ln), "|", 4)
		if len(p) != 4 {
			continue
		}
		sub := Subclass{ID: p[1], Name: p[2]}
		for _, ft := range strings.Split(p[3], " // ") {
			q := strings.SplitN(ft, " ~ ", 3)
			if len(q) != 3 {
				continue
			}
			lvl, _ := strconv.Atoi(strings.TrimSpace(q[0]))
			sub.Feats = append(sub.Feats, Feat{Level: lvl, Name: strings.TrimSpace(q[1]), Desc: strings.TrimSpace(q[2])})
		}
		for i := range dndClasses {
			if dndClasses[i].ID == p[0] {
				dndClasses[i].Subs = append(dndClasses[i].Subs, sub)
			}
		}
	}
	dndClasses = append(dndClasses,
		Class{ID: "mystic", Name: "Мистик", HitDie: 8, Saves: []string{"int", "wis"}, Feats: []Feat{
			f(1, "Психические дисциплины", "Изучаете дисциплины разума: телепатия, сила воли, предвидение. Тратите очки психической энергии."),
			f(1, "Психический фокус", "Сосредоточенность даёт временные HP и бонусы к проверкам."),
			f(2, "Психическая стойкость", "Сопротивление психическому урону и преимущество против очарования."),
			f(3, "Орден мистика", "Подкласс."), f(5, "Психический натиск", "Дополнительное использование дисциплины за ход."),
			f(7, "Телепатическая связь", "Общение на расстоянии с существом, которое вы видели."), f(11, "Разум превыше материи", "Усиленные дисциплины, Мудрость вместо Силы в бою без доспехов."),
			f(17, "Совершенство разума", "Дисциплины без затрат энергии раз за ход.")},
			Subs: []Subclass{
				{ID: "immortal", Name: "Орден бессмертных", Feats: []Feat{f(3, "Стойкость бессмертных", "Временные HP и сопротивление при падении."), f(6, "Несокрушимость", "Раз за отдых остаётесь на ногах с 1 HP.")}},
				{ID: "awakened", Name: "Орден пробуждённых", Feats: []Feat{f(3, "Психическая атака", "Дистанционный психический урон."), f(6, "Волна разума", "Область ошеломления.")}},
				{ID: "elements", Name: "Орден стихий", Feats: []Feat{f(3, "Дары стихий", "Дисциплины огня, воды, воздуха или земли."), f(6, "Стихийный щит", "Сопротивление стихии.")}}}},
		Class{ID: "gunslinger", Name: "Стрелок", HitDie: 8, Saves: []string{"dex", "cha"}, Feats: []Feat{
			f(1, "Огнестрельное оружие", "Владение мушкетами, пистолетами и ружьями; бонус к меткости."),
			f(1, "Меткий глаз", "Бонус к броску атаки по цели в пределах дистанции."),
			f(2, "Манёвр стрелка", "Перекат, быстрая перезарядка, выстрел навскидку."),
			f(3, "Путь стрелка", "Подкласс."), f(5, "Дополнительная атака", "Две атаки за действие."),
			f(7, "Быстрое оружие", "Перезарядка бонусным действием."), f(11, "Смертельный выстрел", "Критический удар на 19–20 по цели в пределах 60 футов."),
			f(17, "Меткость легенды", "Игнорирует укрытие и дальность.")},
			Subs: []Subclass{
				{ID: "sharpshooter", Name: "Снайпер", Feats: []Feat{f(3, "Дальний выстрел", "Удвоенная дальность."), f(7, "Выстрел в слабое место", "Игнорирует часть брони.")}},
				{ID: "desperado", Name: "Головорез", Feats: []Feat{f(3, "Быстрый как молния", "Бонусная атака пистолетом."), f(7, "Дым и пули", "Область отвлекающего огня.")}},
				{ID: "trickshot", Name: "Мастер трюков", Feats: []Feat{f(3, "Рикошет", "Выстрел от поверхности."), f(7, "Огненный залп", "Зажигательный заряд.")}}}},
	)
	for id, t := range extraClassText {
		classText[id] = t
	}
}

var extraClassText = map[string]text{
	"mystic": {"Воин разума, чья сила идёт из психической энергии. Не пользуется заклинаниями, но читает мысли, двигает предметы и укрепляет тело волей.",
		"Мистики возникли в монастырях, где искали магию не в книгах и божествах, а внутри собственного разума. Их орден учит, что воля и есть источник силы, а дисциплины — лишь способ её направить. Неофициальный класс (Unearthed Arcana, 2017)."},
	"gunslinger": {"Меткий стрелок с пороховым оружием: дуэлянт, охотник за головами или бродячий герой.",
		"Огнестрельное оружие редко в мире меча и магии, и стрелки хранят его секреты. Одни обучались у кузнецов, создавших первые мушкеты, другие — на пограничных войнах и в дуэлях. Неофициальный класс (по мотивам класса Мэтта Мёрсера, Critical Role)."},
}
